import { APP_VERSION, APP_ENV, ENABLE_DEV_PLAN_TOGGLE, ENABLE_GLOBAL_METRICS, PAYMENT_PROVIDER, PREMIUM_MONTHLY_PRICE, PREMIUM_YEARLY_PRICE, PREMIUM_MONTHLY_LABEL, PREMIUM_YEARLY_LABEL, ADMIN_EMAILS, getActiveHabitLimit, hasPremiumAccess, planLabel, planStatusLabel, billingCycleLabel, getPlanAlert } from "./plans.js";
import { $, $$, escapeHtml, todayKey, getLastDays, formatTimestamp, getCurrentStreak, getBestStreak, completionRate, MAX_HABIT_NAME_LENGTH } from "./utils.js";
import { setupErrorMonitoring, trackUserAction, logSystemEvent, sanitizeMetadata, errorMetadata, reportFrontendError } from "./error-monitor.js";
