const QUICK_HABITS = ["Beber água", "Ler 10 minutos", "Caminhar", "Meditar", "Estudar"];
const BENEFITS = [["bi-mouse","Simples de usar","Crie, marque e acompanhe hábitos sem telas confusas."],["bi-bullseye","Foco em consistência","Streaks e mensagens motivam pequenas ações diárias."],["bi-bar-chart","Progresso visual","Histórico dos últimos 30 dias para enxergar evolução."],["bi-phone","Feito para celular","Layout mobile first e PWA instalável."],["bi-bell-slash","Sem distrações","Apenas o essencial para sua rotina."],["bi-gift","Gratuito para começar","Até 5 hábitos no plano grátis."]];
let currentUser = null, currentProfile = null, currentSubscription = null, systemSettings = { ...DEFAULT_PUBLIC_SETTINGS, ...COMPANY_INFO }, habits = [], usageEventsCount = 0, unsubscribeHabits = null, pendingDeleteId = null, deferredInstallPrompt = null, pendingSignupEvent = false, adminSummary = null, adminLogs = [], adminErrors = [], adminActivities = [], supportTickets = [], adminSupportTickets = [], adminSupportSummary = null, adminSecuritySummary = null, adminSecurityEvents = [], adminDataRequests = [], chatbotBusy = false, appStart = performance.now();
const modals = {};

function userPath(...parts){return ["users", currentUser.uid, ...parts];}
function profileDoc(userId = currentUser.uid){return firebaseApi.doc(db,"users",userId,"profile","main");}
function habitsCollection(){return firebaseApi.collection(db,...userPath("habits"));}
function habitDocument(id){return firebaseApi.doc(db,...userPath("habits",id));}
function usageCollection(){return firebaseApi.collection(db,...userPath("usageEvents"));}
function activeHabits(){return habits.filter(h => h.isArchived !== true);}
function archivedHabits(){return habits.filter(h => h.isArchived === true);}
function showToast(title,msg,variant="success"){ $("#toastTitle").textContent=title; $("#toastBody").textContent=msg; $("#appToast").className=`toast rounded-4 border-0 toast-${variant}`; modals.toast.show();}
async function handleAppError(error,msg="Não foi possível concluir esta ação.", context={}){ if(APP_ENV === "development") console.error("[HabitFlow Error]", context, error); showToast("Ops",msg,"danger"); try{ await reportFrontendError(error,{...context, action: context.action || "handle_app_error", message: msg}); }catch(logError){ if(APP_ENV === "development") console.warn("Falha ao reportar erro", logError); }}
function setLoading(btn,on,original){ if(!btn) return; btn.disabled=on; btn.innerHTML=on?'<span class="spinner-border spinner-border-sm me-2"></span>Aguarde...':original; }
function canUseDashboard(){ return Boolean(currentProfile?.acceptedTermsAt && currentProfile?.acceptedPrivacyAt); }
function isAdminUser(user){return Boolean(user?.email && ADMIN_EMAILS.includes(user.email));}

function planCardsHtml(){ const premiumActive = hasPremiumAccess(currentProfile, currentSubscription); const checkoutHint = `<p class="small text-secondary mb-2"><i class="bi bi-shield-check me-1"></i>Pagamento em preparação</p>`; return `<div class="col-lg-6"><div class="plan-card h-100"><span class="badge text-bg-success rounded-pill">Entrada</span><h3>Plano Gratuito</h3><div class="price-line"><strong>R$ 0</strong></div><ul><li>Até 5 hábitos ativos</li><li>Histórico de 30 dias</li><li>Streaks e categorias</li><li>PWA instalável</li></ul></div></div><div class="col-lg-3 col-md-6"><div class="plan-card plan-premium h-100"><span class="badge text-bg-dark rounded-pill">Premium</span><h3>Mensal</h3><div class="price-line"><strong>${PREMIUM_MONTHLY_LABEL}</strong></div><ul><li>Hábitos ilimitados</li><li>Histórico completo</li><li>Relatórios avançados</li><li>Desafios futuros</li></ul>${premiumActive?`<div class="alert alert-success rounded-4 py-2">Plano Premium ativo</div>`:checkoutHint}<button class="btn btn-success rounded-pill btn-checkout-monthly" type="button">Assinar mensal</button></div></div><div class="col-lg-3 col-md-6"><div class="plan-card plan-premium h-100"><span class="badge text-bg-success rounded-pill">Melhor valor</span><h3>Anual</h3><div class="price-line"><strong>${PREMIUM_YEARLY_LABEL}</strong></div><ul><li>Economia anual</li><li>Hábitos ilimitados</li><li>Histórico completo</li><li>Prioridade em novidades</li></ul>${premiumActive?`<div class="alert alert-success rounded-4 py-2">Plano Premium ativo</div>`:checkoutHint}<button class="btn btn-outline-success rounded-pill btn-checkout-yearly" type="button">Assinar anual</button></div></div>`;}
function renderMarketing(){ renderSupportButtons(); $("#benefitsGrid").innerHTML=BENEFITS.map(([i,t,txt])=>`<div class="col-md-6 col-lg-4"><div class="feature-card h-100"><i class="bi ${i}"></i><h5>${t}</h5><p>${txt}</p></div></div>`).join(""); $$(".plans-public").forEach(el=>el.innerHTML=planCardsHtml()); bindPremiumButtons();}

async function ensureUserProfile(user){ const ref=profileDoc(user.uid); const snap=await firebaseApi.getDoc(ref); const base={name:user.displayName||user.email||"Usuário",email:user.email||"",photoURL:user.photoURL||"",plan:"free",planStatus:"active",lastLoginAt:firebaseApi.serverTimestamp(),updatedAt:firebaseApi.serverTimestamp(),wantsPremiumNotice:false,appVersion:APP_VERSION,onboardingCompleted:false}; if(snap.exists()){ const old=snap.data(); await firebaseApi.setDoc(ref,{...base,plan:old.plan||"free",planStatus:old.planStatus||(old.plan?"active":"active"),wantsPremiumNotice:old.wantsPremiumNotice===true,onboardingCompleted:old.onboardingCompleted===true,acceptedTermsAt:old.acceptedTermsAt||null,acceptedPrivacyAt:old.acceptedPrivacyAt||null},{merge:true}); } else await firebaseApi.setDoc(ref,{...base,createdAt:firebaseApi.serverTimestamp()},{merge:true}); currentProfile=(await firebaseApi.getDoc(ref)).data()||{};}
async function subscriptionDoc(){return firebaseApi.doc(db,"users",currentUser.uid,"billing","subscription");}
async function loadSubscription(){ if(!currentUser) return; const snap=await firebaseApi.getDoc(await subscriptionDoc()); currentSubscription=snap.exists()?snap.data():null; }
async function refreshProfile(){ currentProfile=(await firebaseApi.getDoc(profileDoc())).data()||{}; await loadSubscription(); renderAll(); }
async function trackEvent(type,metadata={},options={}){ if(!currentUser) return; try{ await trackUserAction(type, sanitizeMetadata(metadata), options); usageEventsCount++; renderAdmin(); }catch(error){ if(APP_ENV === "development") console.warn("[HabitFlow] trackEvent falhou", error); }}
async function updateUserPlan(userId, plan, status){ try{ await firebaseApi.setDoc(profileDoc(userId),{plan,planStatus:status,updatedAt:firebaseApi.serverTimestamp()},{merge:true}); currentProfile={...currentProfile,plan,planStatus:status}; await trackEvent("plan_changed_dev",{plan,status}); showToast("Plano atualizado",`Plano alterado para ${planLabel(plan)} em modo desenvolvimento.`); renderAll(); }catch(error){ await handleAppError(error,"Não foi possível atualizar o plano.",{action:"plan_changed_dev",source:"firestore"}); }}

function setAuthUi(user){ const logged=Boolean(user); $$(".public-only").forEach(el=>el.classList.toggle("d-none",logged)); $$(".auth-only").forEach(el=>el.classList.toggle("d-none",!logged)); $("#adminTabItem").classList.toggle("d-none",!isAdminUser(user)); if(logged){$("#userGreeting").textContent=`Olá, ${user.displayName||user.email||"usuário"}. Acompanhe sua consistência de hoje.`; location.hash="dashboard";} }
function listenHabits(){ if(unsubscribeHabits) unsubscribeHabits(); const started=performance.now(); $("#loadingState").classList.remove("d-none"); const q=firebaseApi.query(habitsCollection(),firebaseApi.orderBy("createdAt","desc")); unsubscribeHabits=firebaseApi.onSnapshot(q,s=>{habits=s.docs.map(d=>({id:d.id,isArchived:false,completedDates:[],...d.data()})); const durationMs=Math.round(performance.now()-started); trackEvent("habits_loaded",{durationMs,habitsCount:habits.length},{severity:durationMs>3000?"warning":"info",message:durationMs>3000?"Carregamento lento detectado":"Hábitos carregados."}).catch(()=>{}); renderAll();},e=>handleAppError(e,"Não foi possível carregar seus hábitos agora.",{source:"firestore", metadata:{functionName:"listenHabits"}}));}
async function loadUsageEventsCount(){ try{ const snap=await firebaseApi.getDocs(firebaseApi.query(usageCollection(),firebaseApi.limit(200))); usageEventsCount=snap.size; renderAdmin(); }catch(e){ if(APP_ENV === "development") console.warn(e); }}
function renderAll(){ renderConsentGate(); renderHabits(); renderProgress(); renderProfile(); renderSupportButtons(); renderAdmin(); renderMySupportTickets(); bindLgpdButtons(); }
function renderConsentGate(){ if(currentUser && !canUseDashboard()) modals.consent.show(); }
function renderHabits(){ $("#loadingState").classList.add("d-none"); const active=activeHabits(), limit=getActiveHabitLimit(currentProfile||{}, currentSubscription||{}); $("#emptyState").classList.toggle("d-none",active.length>0); $("#limitAlert").classList.toggle("d-none",!(active.length>=limit && !hasPremiumAccess(currentProfile||{}, currentSubscription||{}))); const today=todayKey(), done=active.filter(h=>(h.completedDates||[]).includes(today)).length, best=active.reduce((m,h)=>Math.max(m,getBestStreak(h.completedDates)),0); $("#kpiTotal").textContent=active.length; $("#kpiDoneToday").textContent=done; $("#kpiBestStreak").textContent=best; $("#kpiCompletion").textContent=`${active.length?Math.round(done/active.length*100):0}%`; renderQuickHabits(); $("#habitsList").innerHTML=active.map(habitCardHtml).join(""); bindHabitCardEvents(); renderOnboardingHint(); }
function habitCardHtml(h){ const dates=h.completedDates||[], done=dates.includes(todayKey()); const hist=getLastDays(30).map(d=>`<span class="history-day ${dates.includes(d.key)?"done":""} ${d.key===todayKey()?"today":""}" title="${d.label}"></span>`).join(""); return `<article class="habit-card" style="--habit-color:${escapeHtml(h.color||"#10B981")}"><div class="habit-color-bar"></div><div class="habit-title-row"><div><h2 class="habit-title">${escapeHtml(h.name||"Hábito")}</h2><div class="habit-meta">${escapeHtml(h.category||"Outro")} • ${done?"Concluído hoje":"Pendente hoje"}</div></div><div class="habit-actions"><button class="icon-btn btn-edit" data-id="${h.id}" title="Editar"><i class="bi bi-pencil"></i></button><button class="icon-btn btn-delete" data-id="${h.id}" title="Arquivar"><i class="bi bi-archive"></i></button></div></div><button class="check-btn ${done?"done":""}" data-id="${h.id}"><i class="bi ${done?"bi-check-circle-fill":"bi-circle"} me-2"></i>${done?"Feito hoje":"Marcar como feito"}</button><div class="habit-stats"><span class="stat-pill"><i class="bi bi-fire me-1"></i>Streak atual: ${getCurrentStreak(dates)}</span><span class="stat-pill"><i class="bi bi-trophy me-1"></i>Maior: ${getBestStreak(dates)}</span><span class="stat-pill"><i class="bi bi-calendar-check me-1"></i>Total: ${dates.length}</span></div><div class="history-grid">${hist}</div></article>`; }
function bindHabitCardEvents(){ $$(".check-btn").forEach(b=>b.onclick=()=>toggleToday(b.dataset.id)); $$(".btn-edit").forEach(b=>b.onclick=()=>openEdit(b.dataset.id)); $$(".btn-delete").forEach(b=>b.onclick=()=>archiveHabit(b.dataset.id)); }
function renderQuickHabits(){ $("#quickHabits").innerHTML=QUICK_HABITS.map(n=>`<button class="btn btn-outline-success rounded-pill quick-habit-btn" type="button" data-name="${escapeHtml(n)}"><i class="bi bi-plus-lg me-1"></i>${escapeHtml(n)}</button>`).join(""); $$(".quick-habit-btn").forEach(b=>b.onclick=()=>createHabit({name:b.dataset.name,category:"Bem-estar"}));}
function renderOnboardingHint(){ const active=activeHabits(); const anyDone=active.some(h=>(h.completedDates||[]).length); $("#onboardingHint").classList.toggle("d-none",currentProfile?.onboardingCompleted===true); $("#onboardingHint").innerHTML=!active.length?"<b>Comece aqui:</b> 1. Escolha um hábito simples. 2. Marque como feito hoje. 3. Veja sua sequência começar.":!anyDone?"Ótimo começo. Agora marque esse hábito quando concluir hoje.":"Sua primeira sequência começou."; }
function emptyStateHtml(icon,title,text,action){return `<div class="empty-state empty-state-compact"><i class="bi ${icon}"></i><h4>${title}</h4><p>${text}</p><button class="btn btn-success rounded-pill px-4 btn-empty-create" type="button" data-bs-toggle="modal" data-bs-target="#habitModal">${action}</button></div>`;}
function renderProgress(){ const active=activeHabits(); const rate7=completionRate(active,7), rate30=completionRate(active,30); const allDates=[...new Set(active.flatMap(h=>h.completedDates||[]))]; const weekdays=["domingo","segunda","terça","quarta","quinta","sexta","sábado"]; const counts=[0,0,0,0,0,0,0]; allDates.forEach(k=>counts[new Date(`${k}T00:00:00`).getDay()]++); const bestDay=counts.some(Boolean)?weekdays[counts.indexOf(Math.max(...counts))]:"-"; const sorted=[...active].sort((a,b)=>(b.completedDates||[]).length-(a.completedDates||[]).length); $("#reportsList").innerHTML=`<div class="row g-3"><div class="col-sm-6"><div class="metric-card"><span>Taxa 7 dias</span><b>${rate7}%</b><div class="progress"><div class="progress-bar bg-success" style="width:${rate7}%"></div></div></div></div><div class="col-sm-6"><div class="metric-card"><span>Taxa 30 dias</span><b>${rate30}%</b><div class="progress"><div class="progress-bar bg-success" style="width:${rate30}%"></div></div></div></div><div class="col-sm-6"><div class="metric-card"><span>Dias com conclusão</span><b>${allDates.length}</b></div></div><div class="col-sm-6"><div class="metric-card"><span>Melhor dia</span><b>${bestDay}</b></div></div><div class="col-sm-6"><div class="metric-card"><span>Mais conclusões</span><b>${escapeHtml(sorted[0]?.name||"-")}</b></div></div><div class="col-sm-6"><div class="metric-card"><span>Menor frequência</span><b>${escapeHtml(sorted.at(-1)?.name||"-")}</b></div></div></div>`; const messages=[]; if(!active.length) messages.push("Comece com um hábito simples hoje."); else messages.push("Consistência melhora com pequenas ações repetidas."); $("#insightsList").innerHTML=active.length?messages.map(m=>`<div class="insight-item"><i class="bi bi-lightbulb"></i><span>${m}</span></div>`).join(""):emptyStateHtml("bi-graph-up-arrow","Progresso sem dados","Crie e conclua hábitos para receber insights pessoais.","Criar primeiro hábito"); const ranking=[...active].sort((a,b)=>getCurrentStreak(b.completedDates)-getCurrentStreak(a.completedDates)||(b.completedDates||[]).length-(a.completedDates||[]).length); $("#rankingList").innerHTML=ranking.length?ranking.map((h,i)=>`<div class="ranking-item"><b>#${i+1}</b><div><strong>${escapeHtml(h.name)}</strong><span>${escapeHtml(h.category||"Outro")} • ${(h.completedDates||[]).length} conclusões • streak ${getCurrentStreak(h.completedDates)}</span></div></div>`).join(""):emptyStateHtml("bi-trophy","Ranking vazio","Seu ranking aparece quando você criar hábitos.","Criar primeiro hábito"); $("#challengesList").innerHTML=["7 dias de consistência","30 dias sem quebrar a sequência","Semana produtiva","Saúde em foco"].map((t,i)=>`<div class="col-sm-6"><button class="challenge-card w-100" type="button"><span class="badge ${i%2?"text-bg-dark":"text-bg-success"}">${i%2?"Premium futuro":"Gratuito futuro"}</span><h3>${t}</h3><p>Status: Em breve</p></button></div>`).join(""); $$(".challenge-card").forEach(b=>b.onclick=()=>showToast("Desafios","Desafios estarão disponíveis em uma próxima versão.","warning")); }
function renderProfile(){ renderSupportPanel(); $("#profilePlans").innerHTML=`<div class="row g-3">${planCardsHtml()}</div>`; bindPremiumButtons(); $("#profileName").textContent=currentProfile?.name||currentUser?.displayName||"-"; $("#profileEmail").textContent=currentProfile?.email||currentUser?.email||"-"; $("#profilePlan").textContent=planLabel(currentProfile?.plan); $("#profilePlanStatus").textContent=planStatusLabel(currentSubscription?.status || currentProfile?.planStatus || "active"); $("#profileBillingCycle").textContent=billingCycleLabel(currentSubscription?.billingCycle); $("#profileRenewal").textContent=formatTimestamp(currentSubscription?.currentPeriodEnd); $("#profileLimit").textContent=getActiveHabitLimit(currentProfile, currentSubscription)===Infinity?"Ilimitado":"5 hábitos ativos"; $("#profileCreatedAt").textContent=formatTimestamp(currentProfile?.createdAt); $("#profileLastLoginAt").textContent=formatTimestamp(currentProfile?.lastLoginAt); $("#profileTotalHabits").textContent=activeHabits().length; $("#profileTotalCompletions").textContent=activeHabits().reduce((sum,habit)=>sum+(habit.completedDates||[]).length,0); $("#archivedHabitsList").innerHTML=archivedHabits().length?archivedHabits().map(h=>`<div class="ranking-item"><b><i class="bi bi-archive"></i></b><div><strong>${escapeHtml(h.name)}</strong><span>${escapeHtml(h.category||"Outro")} • arquivado em ${formatTimestamp(h.archivedAt)} • ${(h.completedDates||[]).length} conclusões</span><button class="btn btn-sm btn-outline-success rounded-pill mt-2 btn-restore" data-id="${h.id}">Restaurar</button></div></div>`).join(""):"<p class='text-secondary mb-0'>Nenhum hábito arquivado.</p>"; $$(".btn-restore").forEach(b=>b.onclick=()=>restoreHabit(b.dataset.id)); const alert=getPlanAlert(currentProfile,currentSubscription); if(alert) showToast("Assinatura",alert,"warning"); $("#devPlanActions").classList.toggle("d-none",!ENABLE_DEV_PLAN_TOGGLE); $("#btnDevPremiumModal")?.classList.toggle("d-none",!ENABLE_DEV_PLAN_TOGGLE);}
function renderAdmin(){ renderAdminSettings(); if(!$("#adminSummaryCards")) return; if(!isAdminUser(currentUser)){return;} const card=(label,value,icon="bi-activity",variant="success")=>`<div class="col-6 col-lg-3"><div class="kpi-card admin-kpi"><span><i class="bi ${icon} me-1"></i>${label}</span><strong class="text-${variant}">${value ?? 0}</strong></div></div>`; $("#adminSummaryCards").innerHTML=adminSummary?[card("Eventos",adminSummary.totalEvents,"bi-activity"),card("Erros",adminSummary.totalErrors,"bi-bug","danger"),card("Críticos",adminSummary.totalCritical,"bi-exclamation-octagon","danger"),card("Interesses Premium",adminSummary.totalPremiumInterest,"bi-star"),card("Logins recentes",adminSummary.totalLoginsRecent,"bi-box-arrow-in-right"),card("Cadastros recentes",adminSummary.totalSignupsRecent,"bi-person-plus"),card("Últimos bugs",adminSummary.latestErrors?.length||0,"bi-bug"),card("Telegram",adminSummary.telegramEnabled?"ON":"OFF","bi-telegram",adminSummary.telegramEnabled?"success":"secondary")].join(""):`<div class="col-12"><div class="alert alert-light border rounded-4 mb-0">Carregue o resumo administrativo.</div></div>`; $("#adminTelegramEnabled").textContent=adminSummary?.telegramEnabled?"Sim":"Não"; $("#adminTelegramChat").textContent=adminSummary?.telegramChatConfigured?"Sim":"Não"; $("#adminTelegramToken").textContent=adminSummary?.telegramTokenConfigured?"Sim":"Não"; $("#adminTelegramSeverity").textContent=adminSummary?.telegramMinSeverity||"warning"; $("#adminTelegramEvents").textContent=adminSummary?.telegramNotifyEvents||"-"; renderAdminLogs(); renderAdminErrors(); renderAdminActivities(); renderAdminSecurity(); renderAdminLgpd(); renderFunctionsDiagnostics();}


function renderFunctionsDiagnostics(){ const box=$("#adminFunctionsStatus") || $("#adminSupportSettings"); if(!box || !isAdminUser(currentUser)) return; const d=getLoggerDiagnostics(); const html=`<div class="panel-card mt-3" id="adminFunctionsStatus"><div class="d-flex justify-content-between align-items-start flex-wrap gap-2"><div><h3 class="h5 fw-bold">Status das Functions</h3><p class="text-secondary mb-0">Diagnóstico local de conectividade, logger remoto e fila pendente.</p></div><span class="badge text-bg-${d.paused?"warning":"success"}">Remote logger: ${d.paused?"pausado":"ativo"}</span></div><div class="row g-3 my-2"><div class="col-6 col-lg-3"><div class="kpi-card admin-kpi"><span>getPublicSystemSettings</span><strong id="diagSettings">Não testado</strong></div></div><div class="col-6 col-lg-3"><div class="kpi-card admin-kpi"><span>logSystemEvent</span><strong id="diagLogger">${d.paused?"Pausado":"Pronto"}</strong></div></div><div class="col-6 col-lg-3"><div class="kpi-card admin-kpi"><span>Telegram</span><strong id="diagTelegram">Não testado</strong></div></div><div class="col-6 col-lg-3"><div class="kpi-card admin-kpi"><span>Logs pendentes locais</span><strong id="diagPending">${d.pendingLogs}</strong></div></div></div><p class="small text-secondary mb-2">Última falha remota: ${escapeHtml(d.lastRemoteFailure||"-")}</p><div class="d-flex flex-wrap gap-2"><button id="btnDiagHealth" class="btn btn-outline-success rounded-pill btn-sm" type="button">Testar healthCheck</button><button id="btnDiagSettings" class="btn btn-outline-success rounded-pill btn-sm" type="button">Testar getPublicSystemSettings</button><button id="btnDiagLog" class="btn btn-outline-success rounded-pill btn-sm" type="button">Testar logSystemEvent</button><button id="btnFlushLogs" class="btn btn-outline-primary rounded-pill btn-sm" type="button">Enviar logs pendentes</button><button id="btnClearLogs" class="btn btn-outline-secondary rounded-pill btn-sm" type="button">Limpar logs pendentes locais</button><button id="btnDiagTelegram" class="btn btn-outline-danger rounded-pill btn-sm" type="button">Testar Telegram</button></div></div>`; if(box.id==="adminFunctionsStatus") box.outerHTML=html; else if(!$("#adminFunctionsStatus")) box.insertAdjacentHTML("afterend",html); bindFunctionsDiagnostics(); }
function bindFunctionsDiagnostics(){ $("#btnDiagHealth")?.addEventListener("click",async()=>{ const r=await callFunction("healthCheck",{}); showToast("Functions",r.ok?"healthCheck OK":"healthCheck falhou",r.ok?"success":"warning"); }); $("#btnDiagSettings")?.addEventListener("click",async()=>{ const r=await callFunction("getPublicSystemSettings",{}); $("#diagSettings").textContent=r.ok?"OK":"Falhando"; }); $("#btnDiagLog")?.addEventListener("click",async()=>{ await logger.warning("frontend_logger_test","Teste do logger pelo Admin Geral.",{diagnostic:true}); $("#diagLogger").textContent="Teste enviado"; $("#diagPending").textContent=getPendingLogs().length; }); $("#btnFlushLogs")?.addEventListener("click",async()=>{ const r=await flushPendingLogs(); $("#diagPending").textContent=r.pending; showToast("Logger",`Logs enviados: ${r.sent||0}. Pendentes: ${r.pending}.`,r.ok?"success":"warning"); }); $("#btnClearLogs")?.addEventListener("click",()=>{ clearPendingLogs(); $("#diagPending").textContent="0"; showToast("Logger","Fila local limpa."); }); $("#btnDiagTelegram")?.addEventListener("click",async()=>{ await testTelegram(); $("#diagTelegram").textContent="Teste solicitado"; }); }

async function createHabit(data){ try{ if(!currentUser) return; const active=activeHabits(), limit=getActiveHabitLimit(currentProfile||{}, currentSubscription||{}); if(active.length>=limit) return showToast("Limite gratuito","Seu plano gratuito permite até 5 hábitos ativos. Arquive um hábito ou aguarde o Premium.","warning"); await firebaseApi.addDoc(habitsCollection(),{name:data.name,category:data.category||"Outro",color:data.color||"#10B981",createdAt:firebaseApi.serverTimestamp(),updatedAt:firebaseApi.serverTimestamp(),isArchived:false,completedDates:[]}); await trackEvent("habit_created",{category:data.category||"Outro"}); showToast("Hábito criado","Agora é só marcar diariamente."); }catch(error){ await handleAppError(error,"Não foi possível criar o hábito.",{action:"create_habit",source:"firestore"}); }}
async function toggleToday(id){ try{ const h=habits.find(x=>x.id===id); if(!h) return; const set=new Set(h.completedDates||[]), was=set.has(todayKey()); was?set.delete(todayKey()):set.add(todayKey()); await firebaseApi.updateDoc(habitDocument(id),{completedDates:[...set].sort(),updatedAt:firebaseApi.serverTimestamp()}); await trackEvent(was?"habit_uncompleted":"habit_completed",{habitId:id}); if(!was && currentProfile?.onboardingCompleted!==true){ await firebaseApi.setDoc(profileDoc(),{onboardingCompleted:true,updatedAt:firebaseApi.serverTimestamp()},{merge:true}); currentProfile.onboardingCompleted=true; await trackEvent("onboarding_completed"); showToast("Parabéns!","Sua primeira sequência começou."); } else showToast("Progresso atualizado",was?"Conclusão de hoje removida.":"Parabéns! Hábito marcado como feito hoje."); }catch(error){ await handleAppError(error,"Não foi possível atualizar o progresso.",{action:"toggle_habit",source:"firestore"}); }}
function openEdit(id){ const h=habits.find(x=>x.id===id); if(!h) return; $("#habitModalLabel").textContent="Editar hábito"; $("#habitId").value=h.id; $("#habitName").value=h.name||""; $("#habitCategory").value=h.category||"Outro"; $("#habitColor").value=h.color||"#10B981"; $("#btnSaveHabit").textContent="Salvar alterações"; $("#btnCancelEdit").classList.remove("d-none"); modals.habit.show();}
function resetHabitForm(){ $("#habitModalLabel").textContent="Novo hábito"; $("#habitId").value=""; $("#habitForm").reset(); $("#habitColor").value="#10B981"; $("#btnSaveHabit").textContent="Salvar hábito"; $("#btnCancelEdit").classList.add("d-none");}
function archiveHabit(id){ pendingDeleteId=id; modals.confirm.show();}
async function confirmArchiveHabit(){ try{ if(!pendingDeleteId) return; const id=pendingDeleteId; await firebaseApi.updateDoc(habitDocument(id),{isArchived:true,archivedAt:firebaseApi.serverTimestamp(),updatedAt:firebaseApi.serverTimestamp()}); await trackEvent("habit_archived",{habitId:id}); showToast("Hábito arquivado","O hábito saiu da lista principal e pode ser restaurado no Perfil."); pendingDeleteId=null; modals.confirm.hide(); }catch(error){ await handleAppError(error,"Não foi possível arquivar o hábito.",{action:"archive_habit",source:"firestore"}); }}
async function restoreHabit(id){ try{ await firebaseApi.updateDoc(habitDocument(id),{isArchived:false,archivedAt:null,updatedAt:firebaseApi.serverTimestamp()}); await trackEvent("habit_restored",{habitId:id}); showToast("Hábito restaurado","Hábito restaurado com sucesso."); }catch(error){ await handleAppError(error,"Não foi possível restaurar o hábito.",{action:"restore_habit",source:"firestore"}); }}
async function startPremiumCheckout(planType="monthly"){
  if(!currentUser) return showToast("Premium", "Entre ou crie sua conta para assinar o Premium.", "warning");
  try{
    await firebaseApi.setDoc(profileDoc(),{wantsPremiumNotice:true,updatedAt:firebaseApi.serverTimestamp()},{merge:true});
    currentProfile.wantsPremiumNotice=true;
    await trackEvent("premium_checkout_clicked",{provider:PAYMENT_PROVIDER,planType});
    const callable=firebaseApi.httpsCallable(firebaseApi.functions,"createCheckoutSession");
    const result=await callable({planType});
    const data=result.data||{};
    if(data.checkoutUrl && data.mode !== "mock") window.location.href=data.checkoutUrl;
    else showToast("Checkout em modo de teste","Checkout em modo de teste. A estrutura de pagamento já está preparada, mas as credenciais ainda não foram configuradas.","warning");
  }catch(error){ await handleAppError(error,"Não foi possível iniciar o checkout agora.",{action:"start_premium_checkout",source:"functions"}); }
  renderProfile();
}
