async function signInWithGoogle(btn){ const original=btn.innerHTML; setLoading(btn,true,original); try{ await firebaseApi.signInWithPopup(auth,googleProvider); modals.auth.hide(); }catch(e){handleAppError(e,getFriendlyAuthError(e),{action:"login_google",source:"auth",severity:e?.code==="auth/unauthorized-domain"?"critical":"error"});}finally{setLoading(btn,false,original);} }
function getFriendlyAuthError(e){return ({"auth/invalid-email":"E-mail inválido.","auth/user-not-found":"Usuário não encontrado.","auth/wrong-password":"Senha incorreta.","auth/invalid-credential":"E-mail ou senha inválidos.","auth/email-already-in-use":"Este e-mail já está cadastrado.","auth/weak-password":"A senha precisa ter pelo menos 6 caracteres.","auth/popup-closed-by-user":"Login cancelado antes da conclusão.","auth/popup-blocked":"O navegador bloqueou a janela de login. Libere pop-ups e tente novamente.","auth/unauthorized-domain":"Domínio não autorizado no Firebase. Verifique em Firebase Console > Authentication > Settings > Authorized domains.","auth/network-request-failed":"Falha de conexão. Verifique sua internet."}[e?.code]||"Não foi possível concluir a autenticação agora.");}
const firebaseErrorMessage=getFriendlyAuthError;
function clearUserSessionState(){ if(unsubscribeHabits){ unsubscribeHabits(); unsubscribeHabits=null; } habits=[]; supportTickets=[]; adminLogs=[]; adminErrors=[]; adminActivities=[]; adminSecurityEvents=[]; adminDataRequests=[]; adminSummary=null; adminSecuritySummary=null; currentProfile=null; currentSubscription=null; chatbotBusy=false; try{$("#chatbotMessages") && ($("#chatbotMessages").textContent=""); clearPendingLogs();}catch{} }
