function handlePaymentReturn(){ const params=new URLSearchParams(location.search); const payment=params.get("payment"); if(!payment) return; const messages={success:"Pagamento recebido. Seu Premium será ativado em instantes.",pending:"Pagamento em análise. Avisaremos quando for confirmado.",failure:"Não foi possível concluir o pagamento."}; trackEvent(`checkout_${payment}_return`,{payment},{severity:payment==="failure"?"warning":"info"}).catch(()=>{}); showToast("Pagamento",messages[payment]||"Retorno de pagamento recebido.",payment==="failure"?"danger":"success"); history.replaceState({},document.title,location.pathname+location.hash);}
function bindEvents(){ $("#btnGoogle").onclick=()=>signInWithGoogle($("#btnGoogle")); $("#btnHeroGoogle").onclick=()=>signInWithGoogle($("#btnHeroGoogle")); $("#authForm").onsubmit=async e=>{ e.preventDefault(); const btn=$("#btnEmailLogin"), original=btn.innerHTML; setLoading(btn,true,original); try{ try{ await firebaseApi.signInWithEmailAndPassword(auth,$("#authEmail").value.trim(),$("#authPassword").value); }catch(err){ if(["auth/invalid-credential","auth/user-not-found"].includes(err.code)){ await firebaseApi.createUserWithEmailAndPassword(auth,$("#authEmail").value.trim(),$("#authPassword").value); pendingSignupEvent = true; } else throw err; } modals.auth.hide(); $("#authForm").reset(); }catch(err){handleAppError(err,getFriendlyAuthError(err),{action:"login_or_signup_email",source:"auth",severity:err?.code==="auth/unauthorized-domain"?"critical":"error"});}finally{setLoading(btn,false,original);} }; $("#btnLogout").onclick=logout; $("#btnLogoutProfile").onclick=logout; $("#habitForm").onsubmit=async e=>{ e.preventDefault(); const id=$("#habitId").value, name=$("#habitName").value.trim(), category=$("#habitCategory").value, color=$("#habitColor").value; if(!name) return showToast("Nome obrigatório","Informe um nome para o hábito.","warning"); if(name.length>MAX_HABIT_NAME_LENGTH) return showToast("Nome muito longo",`Use no máximo ${MAX_HABIT_NAME_LENGTH} caracteres.`,"warning"); const btn=$("#btnSaveHabit"), original=btn.innerHTML; setLoading(btn,true,original); try{ if(id){ await firebaseApi.updateDoc(habitDocument(id),{name,category,color,updatedAt:firebaseApi.serverTimestamp()}); await trackEvent("habit_updated",{habitId:id}); showToast("Hábito atualizado","As alterações foram salvas."); } else await createHabit({name,category,color}); modals.habit.hide(); resetHabitForm(); }catch(err){handleAppError(err,"Não foi possível salvar o hábito.");}finally{setLoading(btn,false,original);} }; $("#btnCancelEdit").onclick=resetHabitForm; $("#habitModal").addEventListener("hidden.bs.modal",resetHabitForm); $("#btnConfirmDelete").onclick=confirmArchiveHabit; $("#btnAcceptTerms").onclick=acceptTerms; $("#btnDevPremium").onclick=()=>updateUserPlan(currentUser.uid,"premium","trial"); $("#btnDevFree").onclick=()=>updateUserPlan(currentUser.uid,"free","active"); $("#btnUpgradeOpen").onclick=()=>modals.upgrade.show(); $("#btnRefreshAdmin") && ($("#btnRefreshAdmin").onclick=loadAdminDashboard); $("#btnTestTelegram") && ($("#btnTestTelegram").onclick=testTelegram); ["#adminFilterSeverity","#adminFilterType","#adminFilterEmail","#adminFilterEnvironment"].forEach(sel=>$(sel)?.addEventListener("change",loadAdminDashboard)); $("#adminFilterType")?.addEventListener("input",()=>clearTimeout(window.__adminFilterTimer)||(window.__adminFilterTimer=setTimeout(loadAdminDashboard,500))); $("#adminFilterEmail")?.addEventListener("input",()=>clearTimeout(window.__adminFilterTimer)||(window.__adminFilterTimer=setTimeout(loadAdminDashboard,500))); window.addEventListener("beforeinstallprompt",e=>{e.preventDefault(); deferredInstallPrompt=e; $("#installCard")?.classList.remove("d-none");}); $("#btnInstallApp")?.addEventListener("click",async()=>{ if(!deferredInstallPrompt) return; await trackEvent("pwa_install_clicked"); try{ deferredInstallPrompt.prompt(); const choice=await deferredInstallPrompt.userChoice; await logger.info("pwa_install_choice","Usuário respondeu ao prompt PWA.",{outcome:choice?.outcome||"unknown"}); }catch(error){ await handleAppError(error,"Não foi possível instalar o PWA agora.",{action:"pwa_install"}); } deferredInstallPrompt=null; $("#installCard")?.classList.add("d-none");});}
function init(){ setupErrorMonitoring(showToast); trackUserAction("app_loaded",{durationMs:Math.round(performance.now()-appStart),appVersion:APP_VERSION,environment:APP_ENV}).catch(()=>{}); modals.auth=new bootstrap.Modal($("#authModal")); modals.habit=new bootstrap.Modal($("#habitModal")); modals.confirm=new bootstrap.Modal($("#confirmDeleteModal")); modals.consent=new bootstrap.Modal($("#consentModal"),{backdrop:"static",keyboard:false}); modals.upgrade=new bootstrap.Modal($("#upgradeModal")); modals.toast=new bootstrap.Toast($("#appToast")); bindEvents(); initChatbot(); loadPublicSettings().catch(()=>{}); renderMarketing(); firebaseApi.onAuthStateChanged(auth,async user=>{ currentUser=user; setAuthUi(user); if(user){ try{ await ensureUserProfile(user); await loadSubscription(); handlePaymentReturn(); if (pendingSignupEvent) { await trackEvent("signup"); pendingSignupEvent = false; } await trackEvent("login"); flushPendingLogs().catch(()=>{}); await trackEvent("dashboard_loaded",{durationMs:Math.round(performance.now()-appStart)},{severity:performance.now()-appStart>3000?"warning":"info",message:performance.now()-appStart>3000?"Carregamento lento detectado":"Dashboard carregado."}); listenHabits(); loadUsageEventsCount().catch(()=>{}); renderAll(); if(isAdminUser(user)){ await trackEvent("admin_panel_opened"); loadAdminDashboard().catch(()=>{}); loadAdminSupport().catch(()=>{}); } loadMySupportTickets().catch(()=>{}); }catch(e){handleAppError(e,"Não foi possível atualizar seu perfil.");} } else { if(unsubscribeHabits) unsubscribeHabits(); currentProfile=null; currentSubscription=null; habits=[]; usageEventsCount=0; renderAll(); } }); }
init();


function severityBadge(severity){ const cls={info:"secondary",warning:"warning",error:"danger",critical:"dark"}[severity]||"secondary"; return `<span class="badge text-bg-${cls}">${escapeHtml(severity||"info")}</span>`; }
function logDate(value){ return value?.toDate ? value.toDate().toLocaleString("pt-BR") : "-"; }
function adminLogRow(log){ return `<tr><td>${logDate(log.createdAt)}</td><td>${severityBadge(log.severity)}</td><td>${escapeHtml(log.type||"-")}</td><td>${escapeHtml(log.action||"-")}</td><td>${escapeHtml(log.userEmail||log.userName||"-")}</td><td>${escapeHtml(log.message||"-")}</td><td>${escapeHtml(log.environment||"-")}</td><td>${log.telegramSent?"Sim":"Não"}</td><td>${escapeHtml(log.bugStatus||"-")}</td></tr>`; }
function renderAdminLogs(){ if(!$("#adminLogsList")) return; $("#adminLogsList").innerHTML=adminLogs.length?`<div class="table-responsive"><table class="table align-middle admin-table"><thead><tr><th>Data/hora</th><th>Severidade</th><th>Tipo</th><th>Ação</th><th>Usuário</th><th>Mensagem</th><th>Ambiente</th><th>Telegram</th><th>Status bug</th></tr></thead><tbody>${adminLogs.map(adminLogRow).join("")}</tbody></table></div>`:`<div class="empty-state empty-state-compact"><i class="bi bi-inbox"></i><h4>Nenhum evento encontrado</h4><p>Ajuste filtros ou gere eventos no app.</p></div>`; }
function renderAdminErrors(){ if(!$("#adminErrorsList")) return; $("#adminErrorsList").innerHTML=adminErrors.length?adminErrors.map(log=>`<div class="admin-list-item"><div class="d-flex justify-content-between gap-2"><strong>${escapeHtml(log.message||"Erro")}</strong>${severityBadge(log.severity)}</div><small>${logDate(log.createdAt)} • ${escapeHtml(log.source||"-")} • ${escapeHtml(log.userEmail||"-")}</small><code>${escapeHtml(log.errorFingerprint||"sem-fingerprint")}</code><p class="small text-secondary mb-2">${escapeHtml(log.metadata?.sanitizedStack||log.metadata?.errorCode||"")}</p><button class="btn btn-sm btn-outline-success rounded-pill btn-mark-read" data-id="${log.id}">${log.readByAdmin?"Lido":"Marcar como lido"}</button><button class="btn btn-sm btn-outline-primary rounded-pill btn-mark-resolved ms-2" data-id="${log.id}">Resolver</button></div>`).join(""):`<p class="text-secondary mb-0">Nenhum bug recente.</p>`; $$(".btn-mark-read").forEach(b=>b.onclick=()=>markLogAsRead(b.dataset.id)); $$(".btn-mark-resolved").forEach(b=>b.onclick=()=>markBugAsResolved(b.dataset.id)); }
function renderAdminActivities(){ if(!$("#adminActivitiesList")) return; $("#adminActivitiesList").innerHTML=adminActivities.length?adminActivities.map(log=>`<div class="admin-list-item"><strong>${escapeHtml(log.action||log.type)}</strong><small>${logDate(log.createdAt)} • ${escapeHtml(log.userEmail||"-")}</small><p class="mb-0 text-secondary">${escapeHtml(log.message||"")}</p></div>`).join(""):`<p class="text-secondary mb-0">Nenhuma atividade recente.</p>`; }
async function loadAdminDashboard(){ if(!isAdminUser(currentUser)) return; try{ const [summary,logs,errors,activities,security,requests]=await Promise.all([firebaseApi.httpsCallable(firebaseApi.functions,"getAdminDashboardSummary")({}), firebaseApi.httpsCallable(firebaseApi.functions,"getAdminRecentLogs")({severity:$("#adminFilterSeverity")?.value||"",type:$("#adminFilterType")?.value||"",userEmail:$("#adminFilterEmail")?.value||"",environment:$("#adminFilterEnvironment")?.value||"",limit:50}), firebaseApi.httpsCallable(firebaseApi.functions,"getAdminErrorLogs")({limit:50}), firebaseApi.httpsCallable(firebaseApi.functions,"getAdminUserActivitySummary")({}), firebaseApi.httpsCallable(firebaseApi.functions,"getAdminSecuritySummary")({}), firebaseApi.httpsCallable(firebaseApi.functions,"getAdminDataRequests")({})]); adminSummary=summary.data; adminLogs=logs.data?.logs||[]; adminErrors=errors.data?.logs||[]; adminActivities=activities.data?.activities||[]; adminSecuritySummary=security.data; adminSecurityEvents=security.data?.events||[]; adminDataRequests=requests.data?.requests||[]; renderAdmin(); }catch(error){ handleAppError(error,"Não foi possível carregar o Admin Geral.",{type:"unauthorized_admin_attempt",severity:error?.code==="functions/permission-denied"?"critical":"error",metadata:{functionName:"loadAdminDashboard"}}); }}
async function loadAdminSupport(){ if(!isAdminUser(currentUser)) return; const [summary,tickets]=await Promise.all([firebaseApi.httpsCallable(firebaseApi.functions,"getAdminSupportSummary")({}),firebaseApi.httpsCallable(firebaseApi.functions,"getAdminSupportTickets")({})]); adminSupportSummary=summary.data; adminSupportTickets=tickets.data?.tickets||[]; renderAdminSupport(); }
function renderAdminSupport(){ const box=$("#adminSupportPanel"); if(!box || !isAdminUser(currentUser)) return; const card=(label,value)=>`<div class="col-6 col-lg-3"><div class="kpi-card admin-kpi"><span>${label}</span><strong>${value??0}</strong></div></div>`; box.innerHTML=`<div class="panel-card"><div class="d-flex justify-content-between align-items-start gap-2 flex-wrap"><div><h3 class="h5 fw-bold">Suporte</h3><p class="text-secondary mb-0">Chamados acessados por Functions administrativas.</p></div><button id="btnRefreshSupport" class="btn btn-outline-success rounded-pill btn-sm" type="button">Atualizar suporte</button></div><div class="row g-3 my-2">${card("Chamados abertos",adminSupportSummary?.totalOpen)}${card("Bugs abertos",adminSupportSummary?.bugsOpen)}${card("Críticos",adminSupportSummary?.criticalOpen)}${card("Resolvidos",adminSupportSummary?.resolved)}</div><div class="table-responsive"><table class="table align-middle admin-table"><thead><tr><th>Protocolo</th><th>Data</th><th>Usuário</th><th>Tipo</th><th>Prioridade</th><th>Status</th><th>Título</th><th>Ações</th></tr></thead><tbody>${adminSupportTickets.map(t=>`<tr><td>${escapeHtml(t.protocol||t.id)}</td><td>${formatTimestamp(t.createdAt)}</td><td>${escapeHtml(t.userEmail||t.userName||"-")}</td><td>${ticketTypeLabel(t.type)}</td><td>${escapeHtml(t.priority||"-")}</td><td>${ticketStatusLabel(t.status)}</td><td>${escapeHtml(t.title||"")}</td><td><button class="btn btn-sm btn-outline-warning rounded-pill btn-ticket-status" data-id="${escapeHtml(t.id)}" data-status="in_progress">Em análise</button> <button class="btn btn-sm btn-outline-primary rounded-pill btn-ticket-status" data-id="${escapeHtml(t.id)}" data-status="resolved">Resolver</button> <button class="btn btn-sm btn-outline-secondary rounded-pill btn-ticket-status" data-id="${escapeHtml(t.id)}" data-status="closed">Fechar</button></td></tr>`).join("")}</tbody></table></div></div>`; $("#btnRefreshSupport")?.addEventListener("click",()=>loadAdminSupport().catch(e=>handleAppError(e,"Não foi possível atualizar suporte."))); $$(".btn-ticket-status").forEach(b=>b.onclick=()=>updateTicketStatus(b.dataset.id,b.dataset.status)); }
function renderAdminSecurity(){ const box=$("#adminSecurityPanel"); if(!box || !isAdminUser(currentUser)) return; const s=adminSecuritySummary||{}; const card=(label,value)=>`<div class="col-6 col-lg-3"><div class="kpi-card admin-kpi"><span>${label}</span><strong>${escapeHtml(value??0)}</strong></div></div>`; box.innerHTML=`<div class="panel-card"><div class="d-flex justify-content-between align-items-start gap-2 flex-wrap"><div><h3 class="h5 fw-bold">Segurança</h3><p class="text-secondary mb-0">Painel de risco operacional calculado pelas Functions administrativas.</p></div><span class="badge text-bg-${s.riskLevel==="Crítico"?"danger":s.riskLevel==="Alto"?"warning":"success"}">Risco ${escapeHtml(s.riskLevel||"Baixo")}</span></div><div class="row g-3 my-2">${card("Eventos suspeitos 24h",s.suspicious24h)}${card("Admins negados",s.deniedAdmin)}${card("Rate limits",s.rateLimitExceeded)}${card("Erros críticos",s.criticalErrors)}${card("Logs pendentes",s.pendingLogs)}${card("App Check",s.appCheckStatus||"pendente")}${card("Último backup",s.lastBackup||"pendente")}${card("Pipeline",s.pipelineStatus||"manual")}</div><div class="table-responsive"><table class="table align-middle admin-table"><thead><tr><th>Data/hora</th><th>Severidade</th><th>Tipo</th><th>Usuário</th><th>Origem</th><th>Mensagem</th><th>Ação</th><th>Status</th><th>Telegram</th></tr></thead><tbody>${adminSecurityEvents.map(e=>`<tr><td>${logDate(e.createdAt)}</td><td>${severityBadge(e.severity)}</td><td>${escapeHtml(e.type||"-")}</td><td>${escapeHtml(e.userEmail||e.userId||"-")}</td><td>${escapeHtml(e.source||"-")}</td><td>${escapeHtml(e.message||"")}</td><td>${escapeHtml(e.action||"-")}</td><td>${e.readByAdmin?"lido":"pendente"}</td><td>${e.telegramSent?"sim":"não"}</td></tr>`).join("")}</tbody></table></div></div>`; }
function renderAdminLgpd(){ const box=$("#adminLgpdPanel"); if(!box || !isAdminUser(currentUser)) return; box.innerHTML=`<div class="panel-card"><h3 class="h5 fw-bold">Solicitações LGPD</h3><p class="text-secondary">Pedidos de exportação e exclusão são processados operacionalmente pelo Admin Geral.</p><div class="table-responsive"><table class="table align-middle admin-table"><thead><tr><th>Data</th><th>Tipo</th><th>Status</th><th>Usuário</th><th>Ações</th></tr></thead><tbody>${adminDataRequests.map(r=>`<tr><td>${formatTimestamp(r.createdAt)}</td><td>${escapeHtml(r.type)}</td><td>${escapeHtml(r.status)}</td><td>${escapeHtml(r.userEmail||"-")}</td><td><button class="btn btn-sm btn-outline-warning rounded-pill btn-lgpd-status" data-path="${escapeHtml(r.path)}" data-status="reviewing">Em análise</button> <button class="btn btn-sm btn-outline-success rounded-pill btn-lgpd-status" data-path="${escapeHtml(r.path)}" data-status="completed">Concluir</button></td></tr>`).join("")}</tbody></table></div></div>`; $$(".btn-lgpd-status").forEach(b=>b.onclick=()=>updateDataRequestStatus(b.dataset.path,b.dataset.status)); }
