async function updateTicketStatus(ticketId,status){ await safeAsync("update_support_ticket_status",()=>firebaseApi.httpsCallable(firebaseApi.functions,"updateSupportTicketStatus")({ticketId,status}),{successMessage:"Status atualizado.",errorMessage:"Não foi possível atualizar o chamado.",toast:showToast,logSuccess:true}); await loadAdminSupport(); }
async function markLogAsRead(logId){ try{ await firebaseApi.httpsCallable(firebaseApi.functions,"markBugAsRead")({logId}); adminErrors=adminErrors.map(l=>l.id===logId?{...l,readByAdmin:true}:l); renderAdminErrors(); showToast("Admin Geral","Log marcado como lido."); }catch(error){ handleAppError(error,"Não foi possível marcar o log como lido."); }}
async function testTelegram(){ const btn=$("#btnTestTelegram"), original=btn?.innerHTML; if(btn) setLoading(btn,true,original); try{ const result=await firebaseApi.httpsCallable(firebaseApi.functions,"sendTestTelegramAlert")({}); showToast("Telegram", result.data?.success?"Mensagem de teste enviada para o Telegram.":"Não foi possível enviar o teste do Telegram. Verifique as configurações das Functions.", result.data?.success?"success":"warning"); }catch(error){ handleAppError(error,"Não foi possível enviar o teste do Telegram. Verifique as configurações das Functions."); }finally{ if(btn) setLoading(btn,false,original); }}


function supportMailto(){ return `mailto:${systemSettings.commercialEmail||COMPANY_INFO.commercialEmail}`; }
function whatsappLink(){ return buildWhatsappLink(systemSettings); }
function renderSupportButtons(){ const link=whatsappLink(); $$(".hf-whatsapp-slot").forEach(el=>{ el.innerHTML=link?`<a class="btn btn-success rounded-pill" target="_blank" rel="noopener" href="${link}" data-whatsapp-origin="${escapeHtml(el.dataset.origin||"footer")}"><i class="bi bi-whatsapp me-1"></i>${escapeHtml(systemSettings.whatsappButtonText||COMPANY_INFO.whatsappButtonText)}</a>`:""; }); $$("[data-whatsapp-origin]").forEach(a=>a.onclick=()=>trackWhatsappClick(a.dataset.whatsappOrigin)); }
async function trackWhatsappClick(origin){ await logger.info("whatsapp_clicked","Clique em atendimento WhatsApp.",{origin,whatsappEnabled:systemSettings.whatsappEnabled}); }
async function loadPublicSettings(){
  await logger.info("system_settings_loaded_started","Ação iniciada.");
  try{
    const result=await callFunction("getPublicSystemSettings",{}, { silent:true });
    if(result.ok && result.data){ systemSettings={...DEFAULT_PUBLIC_SETTINGS,...COMPANY_INFO,...result.data}; await logger.info("system_settings_loaded","Configurações carregadas com sucesso."); }
    else { systemSettings={...DEFAULT_PUBLIC_SETTINGS,...COMPANY_INFO}; await logger.warning("system_settings_fallback_used","Usando configurações padrão por falha na Function.",{errorCode:result.code}); }
  }catch(error){ systemSettings={...DEFAULT_PUBLIC_SETTINGS,...COMPANY_INFO}; await logger.warning("system_settings_fallback_used","Usando configurações padrão por erro.",{errorCode:error?.code}); }
  renderSupportButtons(); renderSupportPanel();
}
function ticketStatusLabel(status){ return {open:"Aberto",in_progress:"Em análise",resolved:"Resolvido",closed:"Fechado"}[status]||status||"-"; }
function ticketTypeLabel(type){ return {bug:"Bug",support:"Suporte",commercial:"Comercial",premium:"Premium",other:"Outro"}[type]||type||"-"; }
async function loadMySupportTickets(){ if(!currentUser) return; const result=await safeAsync("get_my_support_tickets",()=>firebaseApi.httpsCallable(firebaseApi.functions,"getMySupportTickets")({}),{logError:true}); supportTickets=result?.data?.tickets||[]; renderMySupportTickets(); }
function renderMySupportTickets(){ const box=$("#mySupportTickets"); if(!box) return; box.innerHTML=supportTickets.length?supportTickets.map(t=>`<div class="support-ticket-item"><div class="d-flex justify-content-between gap-2"><strong>${escapeHtml(t.protocol||t.id)}</strong><span class="badge text-bg-${t.status==="open"?"success":t.status==="in_progress"?"warning":t.status==="resolved"?"primary":"secondary"}">${ticketStatusLabel(t.status)}</span></div><small>${ticketTypeLabel(t.type)} • ${formatTimestamp(t.updatedAt||t.createdAt)}</small><p class="mb-0 text-secondary small">${escapeHtml(t.title||"")}</p></div>`).join(""):`<p class="text-secondary mb-0">Nenhum chamado aberto ainda.</p>`; }
function renderSupportPanel(){ const box=$("#profileSupportBox"); if(!box) return; const link=whatsappLink(); box.innerHTML=`<h2 class="h5 fw-bold">Central de Suporte</h2><p class="text-secondary">Atendimento HabitFlow por assistente, WhatsApp configurável e e-mail MNSOFT.</p><dl class="profile-list"><dt>Empresa</dt><dd>${escapeHtml(systemSettings.companyName)}</dd><dt>Razão social</dt><dd>${escapeHtml(systemSettings.companyLegalName)}</dd><dt>CNPJ</dt><dd>${escapeHtml(systemSettings.companyCnpj)}</dd><dt>E-mail</dt><dd><a href="${supportMailto()}" id="profileSupportEmail">${escapeHtml(systemSettings.commercialEmail)}</a></dd></dl><div class="d-flex flex-wrap gap-2 mb-3"><button class="btn btn-outline-secondary rounded-pill" type="button" id="btnOpenChatbotProfile">Abrir Assistente HabitFlow</button><button class="btn btn-outline-danger rounded-pill" type="button" id="btnReportBugProfile">Reportar bug</button>${link?`<a class="btn btn-success rounded-pill" target="_blank" rel="noopener" href="${link}" data-whatsapp-origin="profile">${escapeHtml(systemSettings.whatsappButtonText)}</a>`:""}<a class="btn btn-outline-success rounded-pill" href="${supportMailto()}" id="btnSupportEmailProfile">Enviar e-mail</a></div><h3 class="h6 fw-bold">Meus chamados</h3><div id="mySupportTickets" class="support-ticket-list"></div>`; $("#btnOpenChatbotProfile")?.addEventListener("click",openChatbot); $("#btnReportBugProfile")?.addEventListener("click",openBugReport); $("#btnSupportEmailProfile")?.addEventListener("click",()=>logger.info("chatbot_email_clicked","Clique em e-mail pelo Perfil.")); $$("[data-whatsapp-origin]").forEach(a=>a.onclick=()=>trackWhatsappClick(a.dataset.whatsappOrigin)); renderMySupportTickets(); }
function renderAdminSettings(){ const box=$("#adminSupportSettings"); if(!box || !isAdminUser(currentUser)) return; box.innerHTML=`<h3 class="h5 fw-bold">Configurações de Atendimento</h3><div class="row g-2"><div class="col-md-6"><label class="form-label">Empresa</label><input id="setCompanyName" class="form-control" value="${escapeHtml(systemSettings.companyName)}"></div><div class="col-md-6"><label class="form-label">CNPJ</label><input id="setCnpj" class="form-control" value="${escapeHtml(systemSettings.companyCnpj)}"></div><div class="col-md-6"><label class="form-label">E-mail comercial</label><input id="setEmail" class="form-control" value="${escapeHtml(systemSettings.commercialEmail)}"></div><div class="col-md-6"><label class="form-label">WhatsApp</label><input id="setWhatsapp" class="form-control" placeholder="5591999999999" value="${escapeHtml(systemSettings.whatsappNumber||"")}"></div><div class="col-12"><label class="form-label">Mensagem padrão</label><input id="setMessage" class="form-control" value="${escapeHtml(systemSettings.whatsappDefaultMessage)}"></div><div class="col-md-6"><label class="form-label">Texto do botão</label><input id="setButtonText" class="form-control" value="${escapeHtml(systemSettings.whatsappButtonText)}"></div><div class="col-md-6 d-flex align-items-end"><div class="form-check"><input id="setWhatsappEnabled" class="form-check-input" type="checkbox" ${systemSettings.whatsappEnabled?"checked":""}><label class="form-check-label" for="setWhatsappEnabled">Ativar WhatsApp</label></div></div></div><button id="btnSaveSystemSettings" class="btn btn-success rounded-pill mt-3" type="button">Salvar configurações</button>`; $("#btnSaveSystemSettings").onclick=saveSystemSettings; }
async function saveSystemSettings(){ const data={companyName:$("#setCompanyName").value,companyCnpj:$("#setCnpj").value,commercialEmail:$("#setEmail").value,whatsappNumber:$("#setWhatsapp").value,whatsappDefaultMessage:$("#setMessage").value,whatsappButtonText:$("#setButtonText").value,whatsappEnabled:$("#setWhatsappEnabled").checked}; const result=await safeAsync("update_system_settings",()=>firebaseApi.httpsCallable(firebaseApi.functions,"updateSystemSettings")(data),{errorMessage:"Não foi possível salvar as configurações.",successMessage:"Configurações salvas.",toast:showToast,logSuccess:true}); if(result?.data?.settings){ systemSettings={...COMPANY_INFO,...result.data.settings}; renderAll(); } }
function initChatbot(){ if($("#chatbotWidget")) return; document.body.insertAdjacentHTML("beforeend",`<div id="chatbotWidget" class="chatbot-widget"><button id="chatbotToggle" class="btn btn-success rounded-pill shadow-soft" aria-label="Abrir Assistente HabitFlow"><i class="bi bi-chat-dots me-1"></i>Ajuda</button><section id="chatbotPanel" class="chatbot-panel d-none" aria-label="Assistente HabitFlow"><header><div><strong>Assistente HabitFlow</strong><span class="chatbot-online"><i class="bi bi-circle-fill"></i> Online</span></div><button id="chatbotClose" class="icon-btn" type="button" aria-label="Minimizar assistente"><i class="bi bi-dash-lg"></i></button></header><div class="chatbot-warning"><i class="bi bi-shield-lock me-1"></i>Não envie senhas, CPF, cartão, tokens ou dados sensíveis.</div><div id="chatbotMessages" class="chatbot-messages" aria-live="polite"></div><div id="chatbotTyping" class="chatbot-typing d-none">Assistente digitando...</div><div class="chatbot-quick"><button type="button">Como criar um hábito?</button><button type="button">Como funciona o streak?</button><button type="button">Quero falar com suporte</button><button type="button">Encontrei um bug</button><button type="button">Quero saber do Premium</button><button type="button">Como funciona minha privacidade?</button></div><form id="chatbotForm" class="chatbot-form"><input id="chatbotInput" class="form-control" maxlength="1000" placeholder="Digite sua dúvida" aria-label="Mensagem para o Assistente HabitFlow"><button id="chatbotSend" class="btn btn-success" type="submit">Enviar</button></form><div class="chatbot-actions"><span class="hf-whatsapp-slot" data-origin="chatbot"></span><a class="btn btn-outline-success rounded-pill btn-sm" href="mailto:comercial@mnsoft.com.br" id="chatbotEmail">E-mail</a><button class="btn btn-outline-danger rounded-pill btn-sm" id="chatbotBug" type="button">Reportar bug</button><button class="btn btn-outline-secondary rounded-pill btn-sm" id="chatbotClear" type="button">Limpar</button></div></section></div>`); $("#chatbotToggle").onclick=openChatbot; $("#chatbotClose").onclick=()=>{ $("#chatbotPanel").classList.add("d-none"); logger.info("chatbot_closed","Chatbot minimizado."); }; $("#chatbotForm").onsubmit=e=>{e.preventDefault(); handleChatbotMessage($("#chatbotInput").value);}; $$(".chatbot-quick button").forEach(b=>b.onclick=()=>handleChatbotMessage(b.textContent)); $("#chatbotBug").onclick=()=>openBugReport(); $("#chatbotClear").onclick=()=>{$("#chatbotMessages").innerHTML=""; addBotMessage("Conversa local limpa. Como posso ajudar?");}; $("#chatbotEmail").onclick=()=>logger.info("chatbot_email_clicked","Clique em e-mail pelo chatbot."); addBotMessage("Olá! Sou o Assistente HabitFlow. Posso ajudar você a usar o sistema, entender seus hábitos ou falar com o suporte."); renderSupportButtons(); }
function openChatbot(){ $("#chatbotPanel")?.classList.remove("d-none"); logger.info("chatbot_opened","Chatbot aberto."); }
function addBotMessage(text,actions=[]){ const el=document.createElement("div"); el.className="chatbot-msg bot"; el.textContent=String(text||"").slice(0,1200); $("#chatbotMessages").appendChild(el); if(actions?.length){ const bar=document.createElement("div"); bar.className="chatbot-action-row"; bar.innerHTML=actions.map(a=>`<button class="btn btn-sm btn-outline-success rounded-pill" type="button" data-action="${escapeHtml(a.action)}">${escapeHtml(a.label)}</button>`).join(""); $("#chatbotMessages").appendChild(bar); bar.querySelectorAll("button").forEach(b=>b.onclick=()=>handleChatbotAction(b.dataset.action)); } el.scrollIntoView({block:"end"}); }
function addUserMessage(text){ const el=document.createElement("div"); el.className="chatbot-msg user"; el.textContent=String(text||"").slice(0,1000); $("#chatbotMessages").appendChild(el); el.scrollIntoView({block:"end"}); }
function handleChatbotAction(action){ if(action==="report_bug") return openBugReport(); if(action==="whatsapp"){ const link=whatsappLink(); if(link) window.open(link,"_blank","noopener"); else location.href=supportMailto(); return trackWhatsappClick("chatbot"); } if(action==="email") return location.href=supportMailto(); if(action==="premium_interest") return handlePremiumInterest(); if(action==="new_habit") return modals.habit?.show(); if(action==="profile") return document.querySelector('[data-bs-target="#tabPerfil"]')?.click(); if(action==="progress") return document.querySelector('[data-bs-target="#tabProgresso"]')?.click(); }
async function handleChatbotMessage(rawText){ const text=String(rawText||"").trim(); if(!text) return showToast("Assistente","Digite uma mensagem antes de enviar.","warning"); if(text.length>1000) return showToast("Assistente","Mensagem muito longa. Use até 1000 caracteres.","warning"); if(chatbotBusy) return; chatbotBusy=true; const btn=$("#chatbotSend"), original=btn?.innerHTML; setLoading(btn,true,original); $("#chatbotInput").value=""; addUserMessage(text); $("#chatbotTyping")?.classList.remove("d-none"); const local=detectIntent(text); const meta={intent:local.intent,messageLength:text.length,blocked:local.blocked===true,mode:DEFAULT_CHATBOT_MODE}; await logger.info("chatbot_message_sent","Mensagem enviada ao chatbot.",meta); try{ let response=null; if(currentUser){ const callable=firebaseApi.httpsCallable(firebaseApi.functions,"askHabitFlowAssistant"); response=(await callable({message:text,context:{screen:location.hash||"home",userPlan:currentProfile?.plan||"free",appVersion:APP_VERSION,environment:APP_ENV}})).data; } const result=response||{answer:local.reply,intent:local.intent,source:"rules",suggestedActions:local.actions||[],safetyBlocked:local.blocked===true}; if(result.safetyBlocked) await logger.warning("chatbot_sensitive_request_blocked","Solicitação sensível bloqueada.",meta); if(result.intent==="unknown") await logger.warning("chatbot_unknown_question","Pergunta sem resposta conhecida.",meta); if(["bug_report","technical_problem"].includes(result.intent)) await logger.warning("chatbot_bug_report_started","Usuário iniciou relato de bug.",meta); addBotMessage(result.answer,result.suggestedActions); await logger.info("chatbot_response_generated","Resposta segura gerada pelo chatbot.",{...meta,source:result.source}); }catch(error){ await handleAppError(error,"Não consegui responder agora. Você pode tentar novamente ou falar com o suporte.",{action:"chatbot_error"}); addBotMessage("Não consegui responder agora. Você pode tentar novamente ou falar com o suporte.",local.actions); }finally{ $("#chatbotTyping")?.classList.add("d-none"); chatbotBusy=false; setLoading(btn,false,original); } }
async function createSupportTicketFromUi(type,title,description,screen,priority="medium",source="chatbot"){ const result=await safeAsync("create_support_ticket",()=>firebaseApi.httpsCallable(firebaseApi.functions,"createSupportTicket")({type,title,description,screen,priority,source}),{errorMessage:"Não foi possível criar o chamado agora.",toast:showToast,logSuccess:true}); if(result?.data?.ticket){ supportTickets=[result.data.ticket,...supportTickets]; renderMySupportTickets(); await logger.info("chatbot_ticket_created","Chamado criado pelo atendimento.",{protocol:result.data.ticket.protocol,type}); return result.data.ticket; } return null; }
async function openBugReport(){ const happened=prompt("O que aconteceu? Não envie senhas, CPF, cartão ou tokens."); if(!happened) return; const sensitive=detectSensitiveContent(happened); const screen=prompt("Em qual tela isso aconteceu?")||"não informado"; const blocking=confirm("Isso impede você de usar o sistema?"); const ticket=await createSupportTicketFromUi("bug","Bug reportado pelo usuário",sensitive.blocked?"[mensagem bloqueada por segurança]":happened,screen,blocking?"high":"medium","chatbot"); if(ticket) showToast("Suporte",`Obrigado! Registrei seu problema para análise. Protocolo: ${ticket.protocol}.`,"success"); }
async function markBugAsResolved(logId){ try{ await firebaseApi.httpsCallable(firebaseApi.functions,"markBugAsResolved")({logId}); adminErrors=adminErrors.filter(l=>l.id!==logId); renderAdminErrors(); showToast("Admin Geral","Bug marcado como resolvido."); }catch(error){ handleAppError(error,"Não foi possível resolver o bug."); }}
